\newcommand{\Z}{\mathbb{Z}}
\newcommand{\Zn}{\mathbb{Z}_n}
\newcommand{\gcdd}{\gcd}

\title{An Algebraic Characterization of Panmagic Affine Permutations over $\mathbb{Z}_n$}
\author{Aristotle}
\date{2026-06-27}

\begin{document}

\begin{abstract}
We study affine self-maps $\sigma_{a,b}(x) = a x + b$ of the cyclic ring
$\Zn = \Z/n\Z$ and determine precisely when they generate \emph{panmagic}
(pandiagonal) structures. We call $\sigma_{a,b}$ \emph{panmagic} when it is
simultaneously a permutation, an \emph{orthomorphism} (the difference map
$x \mapsto \sigma(x) - x$ is a permutation), and a \emph{complete mapping} (the
sum map $x \mapsto \sigma(x) + x$ is a permutation). Our central structural
result reduces this triple condition to a single arithmetic statement:
$\sigma_{a,b}$ is panmagic if and only if the three consecutive ring elements
$a$, $a - 1$, and $a + 1$ are all units of $\Zn$. From this we derive a sharp
existence theorem: a panmagic affine permutation of $\Zn$ exists if and only if
$\gcdd(n, 6) = 1$, with the universal witness $a = 2$ working for every
admissible modulus. We also describe the enumeration of such maps via a
multiplicative counting function and outline generalizations.
\end{abstract}

\maketitle

\section{Introduction}

A \emph{magic square} of order $n$ is an $n \times n$ array of symbols whose
every row and column (and, classically, both main diagonals) forms a transversal.
The most symmetric variant is the \emph{pandiagonal} or \emph{panmagic} square,
in which all broken diagonals, in both slant directions, are also transversals.
Viewing the array on the discrete torus $\Zn \times \Zn$, the broken diagonals
are the orbits of the shear lines $y - x = \text{const}$ and
$y + x = \text{const}$, of which there are $2n$ in total.

A classical way to manufacture such arrays is to derive them from a permutation
$\sigma$ of $\Zn$. Under this dictionary the rows and columns are transversals
when $\sigma$ is a bijection, the positively sloped broken diagonals are
transversals precisely when $x \mapsto \sigma(x) - x$ is a bijection, and the
negatively sloped broken diagonals precisely when $x \mapsto \sigma(x) + x$ is a
bijection. A permutation whose difference map is again a permutation is an
\emph{orthomorphism}; one whose sum map is again a permutation is a
\emph{complete mapping}. A permutation that is both yields a pandiagonal Latin
square; we call it \emph{panmagic}.

The simplest non-trivial family of permutations of $\Zn$ is the family of
\emph{affine maps} $\sigma_{a,b}(x) = a x + b$, the elements of the affine group
$\mathrm{Aff}(\Zn)$. We give a complete, elementary, and rigorous algebraic
characterization of which affine maps are panmagic, and settle the existence
question for every modulus.

\section{Definitions and conventions}

Throughout, $n$ is a positive integer and $\Zn = \Z/n\Z$. An element
$a \in \Zn$ is a \emph{unit} iff there exists $a^{-1}$ with $a a^{-1} = 1$;
equivalently iff $\gcdd(\tilde a, n) = 1$ for an integer representative
$\tilde a$.

\begin{definition}[Affine map]
For $a, b \in \Zn$, the \emph{affine map} is
$\sigma_{a,b} : \Zn \to \Zn$, $\sigma_{a,b}(x) = a x + b$.
\end{definition}

\begin{definition}[Orthomorphism]
A permutation $\sigma$ of $\Zn$ is an \emph{orthomorphism} if
$x \mapsto \sigma(x) - x$ is also a permutation.
\end{definition}

\begin{definition}[Complete mapping]
A permutation $\sigma$ of $\Zn$ is a \emph{complete mapping} if
$x \mapsto \sigma(x) + x$ is also a permutation.
\end{definition}

\begin{definition}[Panmagic affine map]
The affine map $\sigma_{a,b}$ is \emph{panmagic} if it is a permutation, an
orthomorphism, and a complete mapping; that is, if all three of
$x \mapsto \sigma_{a,b}(x)$, $x \mapsto \sigma_{a,b}(x) - x$, and
$x \mapsto \sigma_{a,b}(x) + x$ are bijections of $\Zn$.
\end{definition}

\section{The unit criterion for affine bijections}

\begin{lemma}[Unit criterion]\label{lem:unit}
Let $R$ be a commutative ring and $c, d \in R$. The map $f(x) = c x + d$ is a
bijection of $R$ if and only if $c$ is a unit.
\end{lemma}

\begin{proof}
($\Leftarrow$) If $u = c^{-1}$ exists, then $g(y) = u(y - d)$ satisfies
$f(g(y)) = y$ and $g(f(x)) = x$, so $f$ is bijective. ($\Rightarrow$) If $f$ is
surjective, pick $x$ with $f(x) = 1 + d$, so $c x = 1$ and $c$ is a unit.
Surjectivity alone forces $c$ to be a unit; no finiteness is needed.
\end{proof}

\begin{proposition}[Bijectivity]\label{prop:bij}
$\sigma_{a,b}$ is a permutation of $\Zn$ if and only if $a$ is a unit.
\end{proposition}

\begin{proof}
Instance of Lemma~\ref{lem:unit} with $c = a$, $d = b$.
\end{proof}

\section{Diagonal characterizations}

\begin{proposition}[Orthomorphism criterion]\label{prop:ortho}
$\sigma_{a,b}$ is an orthomorphism iff $a - 1$ is a unit.
\end{proposition}

\begin{proof}
For all $x$, $\sigma_{a,b}(x) - x = (a-1)x + b$, an affine map with multiplier
$a - 1$; apply Lemma~\ref{lem:unit}.
\end{proof}

\begin{proposition}[Complete-mapping criterion]\label{prop:cm}
$\sigma_{a,b}$ is a complete mapping iff $a + 1$ is a unit.
\end{proposition}

\begin{proof}
For all $x$, $\sigma_{a,b}(x) + x = (a+1)x + b$; apply Lemma~\ref{lem:unit}.
\end{proof}

The additive constant $b$ is preserved in both computations; it never affects
bijectivity, foreshadowing that panmagicness is independent of $b$.

\section{The algebraic characterization}

\begin{theorem}[Algebraic characterization]\label{thm:char}
For all $a, b \in \Zn$, $\sigma_{a,b}$ is panmagic if and only if $a$, $a - 1$,
and $a + 1$ are all units of $\Zn$.
\end{theorem}

\begin{proof}
By definition $\sigma_{a,b}$ is panmagic iff the three maps $\sigma_{a,b}$,
$\sigma_{a,b}(\cdot) - \mathrm{id}$, $\sigma_{a,b}(\cdot) + \mathrm{id}$ are
bijections. By Propositions~\ref{prop:bij}, \ref{prop:ortho}, \ref{prop:cm} these
hold iff $a$, $a - 1$, $a + 1$ (respectively) are units. Conjoining gives the
claim.
\end{proof}

\section{Existence: the role of $2$ and $3$}

\begin{lemma}[No solution mod 2]\label{lem:two}
There is no $x \in \Z_2$ for which both $x$ and $x - 1$ are units.
\end{lemma}

\begin{proof}
$\Z_2 = \{0,1\}$: if $x = 0$ then $x$ is not a unit; if $x = 1$ then $x - 1 = 0$
is not a unit.
\end{proof}

\begin{lemma}[No solution mod 3]\label{lem:three}
There is no $x \in \Z_3$ for which all of $x$, $x - 1$, $x + 1$ are units.
\end{lemma}

\begin{proof}
The three consecutive residues $x - 1, x, x + 1$ cover all of $\{0,1,2\}$ mod
$3$, so one equals $0$, not a unit.
\end{proof}

\begin{lemma}[Obstruction at 2]\label{lem:obstr2}
If $a$ and $a - 1$ are units of $\Zn$, then $2 \nmid n$.
\end{lemma}

\begin{proof}
If $2 \mid n$, reduction $\pi : \Zn \to \Z_2$ is a ring homomorphism sending
units to units, so $\pi(a)$ and $\pi(a) - 1$ are units of $\Z_2$, contradicting
Lemma~\ref{lem:two}.
\end{proof}

\begin{lemma}[Obstruction at 3]\label{lem:obstr3}
If $a$, $a - 1$, $a + 1$ are units of $\Zn$, then $3 \nmid n$.
\end{lemma}

\begin{proof}
If $3 \mid n$, reduce along $\pi : \Zn \to \Z_3$; then $\pi(a)$, $\pi(a) - 1$,
$\pi(a) + 1$ are units of $\Z_3$, contradicting Lemma~\ref{lem:three}.
\end{proof}

\begin{lemma}[Witness $a = 2$]\label{lem:witness}
If $\gcdd(n, 6) = 1$, then $\sigma_{2,0}$ is panmagic.
\end{lemma}

\begin{proof}
With $a = 2$ the required units are $a - 1 = 1$, $a = 2$, $a + 1 = 3$. Now $1$ is
always a unit, and $\gcdd(n,6)=1$ makes $2$ and $3$ units. Apply
Theorem~\ref{thm:char}.
\end{proof}

\begin{theorem}[Existence]\label{thm:exist}
A panmagic affine permutation of $\Zn$ exists if and only if $\gcdd(n, 6) = 1$.
\end{theorem}

\begin{proof}
($\Rightarrow$) If $\sigma_{a,b}$ is panmagic, Theorem~\ref{thm:char} gives $a$,
$a-1$, $a+1$ units, and Lemmas~\ref{lem:obstr2}, \ref{lem:obstr3} give
$2 \nmid n$, $3 \nmid n$, i.e. $\gcdd(n,6)=1$. ($\Leftarrow$)
Lemma~\ref{lem:witness} supplies $\sigma_{2,0}$.
\end{proof}

The admissible moduli are exactly those coprime to $6$:
$n \in \{1, 5, 7, 11, 13, 17, 19, 23, 25, \dots\}$.

\section{Enumeration}

Since panmagicness is independent of $b$, the number of panmagic affine
permutations of $\Zn$ is $N(n) = n \cdot P(n)$, where
$P(n) = \#\{a \in \Zn : a, a-1, a+1 \text{ all units}\}$.

\begin{proposition}[Multiplicative count]\label{prop:count}
The function $P$ is multiplicative, and on prime powers
\[
P(p^k) = \begin{cases} 0, & p \in \{2,3\}, \\ p^{k-1}(p-3), & p \ge 5.\end{cases}
\]
Hence $P(n) = \prod_{p^k \,\|\, n} p^{k-1}(p-3)$ with $P(1) = 1$, and $P(n) > 0$
iff $\gcdd(n,6)=1$, recovering Theorem~\ref{thm:exist}.
\end{proposition}

\begin{proof}
Multiplicativity follows from the Chinese Remainder isomorphism
$\Z_{mn} \cong \Z_m \times \Z_n$ for coprime $m, n$. For $p \ge 5$, an element is
bad exactly when $a \equiv 0, 1, -1 \pmod p$ (three distinct residues), each
lifting to $p^{k-1}$ residues mod $p^k$; removing them leaves
$p^k - 3p^{k-1} = p^{k-1}(p-3)$. For $p \in \{2,3\}$ the count is $0$ by
Lemmas~\ref{lem:two}, \ref{lem:three}.
\end{proof}

For example $N(5) = 10$, $N(7) = 28$, $N(25) = 250$, $N(35) = 280$, all
verifiable by exhaustive search.

\section{Worked examples}

Each statement below is mechanically checkable by exhaustive search and
independently confirms Theorems~\ref{thm:char}, \ref{thm:exist} and
Proposition~\ref{prop:count}.

\textbf{$n = 5$.} $\gcdd(5,6)=1$, so panmagic maps exist. The bad residues are
$0,1,4 \pmod 5$, leaving $a \in \{2,3\}$; thus $P(5) = 2 = 5^0(5-3)$ and
$N(5) = 10$. The witness $a = 2$, $b = 0$ yields the pandiagonal array
$\mathrm{cell}(i,j) = (2i + j) \bmod 5$.

\textbf{$n = 7$.} Bad residues $0,1,6$ leave $a \in \{2,3,4,5\}$, so
$P(7) = 4 = 7 - 3$ and $N(7) = 28$.

\textbf{$n = 25$.} The bad residues $0,1,4 \pmod 5$ each lift to $5$ residues
mod $25$; removing $15$ from $25$ leaves $P(25) = 10 = 5^1(5-3)$ and
$N(25) = 250$.

\textbf{$n = 35 = 5\cdot 7$.} By multiplicativity $P(35) = 2 \cdot 4 = 8$ and
$N(35) = 280$.

\textbf{$n = 6$.} Divisible by $2$ and $3$, so $P(6) = 0$ and $N(6) = 0$: no
panmagic affine permutation exists.

\section{Discussion and future work}

The results are sharp and complete for the one-dimensional affine single-step
case. Natural extensions include: an enumeration via the multiplicative $P$
(Proposition~\ref{prop:count}); an \emph{$r$-panmagic} notion requiring
$x \mapsto \sigma(x) + jx$ to be a permutation for all $|j| \le r$ (conjecturally
existing iff every prime divisor of $n$ exceeds $2r+1$, witness $a = r+1$); an
\emph{orthogonality} bound for families of pairwise-orthogonal affine
permutations ($a - c$ a unit); and higher-dimensional analogues over finite
commutative rings $R$ or $(\Zn)^d$, where the criterion becomes invertibility of
$A$, $A - I$, $A + I$.

\section{Conclusion}

The geometric notion of a panmagic affine permutation of $\Zn$ collapses to the
simultaneous invertibility of three consecutive elements $a$, $a-1$, $a+1$, and
existence is governed by the single condition $\gcdd(n,6)=1$, with $a = 2$ a
universal witness. The argument is elementary, constructive, and yields efficient
decision, witness-generation, and counting algorithms.

\end{document}

