function IS_PANMAGIC(n, a, b):
    # b is irrelevant; panmagicness depends only on the multiplier a
    if gcd(a mod n, n) != 1:        return false   # a not a unit (rows/cols fail)
    if gcd((a-1) mod n, n) != 1:    return false   # a-1 not a unit (orthomorphism fails)
    if gcd((a+1) mod n, n) != 1:    return false   # a+1 not a unit (complete mapping fails)
    return true

function PANMAGIC_WITNESS(n):
    if gcd(n, 6) == 1:
        return (a := 2 mod n, b := 0)   # certified panmagic by the unit criterion
    else:
        return NONE                      # no panmagic affine map exists

